target.css:
:root {
  --ink: #26352c;
  --moss: #52715b;
  --mint: #dcebd8;
  --paper: #fffdf5;
  --sun: #f4c858;
}

.survey-tag {
  width: 440px;
  box-sizing: border-box;
  padding: 16px;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

header,
footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

header {
  padding-bottom: 10px;
  border-bottom: 1px solid var(--moss);
  color: var(--moss);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

section {
  padding: 12px 0;
}

.icon {
  margin: 0 0 3px;
  font-size: 22px;
  line-height: 1;
}

h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1.15;
}

.details {
  margin: 5px 0 0;
  color: var(--moss);
  font-size: 14px;
  line-height: 1.45;
}

footer {
  padding-top: 10px;
  border-top: 1px solid var(--moss);
}

.status {
  padding: 4px 8px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--moss);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.7px;
}

button {
  padding: 7px 11px;
  border: 0;
  border-radius: 7px;
  background: var(--sun);
  color: var(--ink);
  font-size: 13px;
  font-weight: 700;
}

